INSERT INTO publications (id, album_name, artist, condition, created_at, description, genre, image_uris, name, price, release_year, format, user_id) VALUES
(2, 'Rubber Soul', 'The Beatles', 'EXCELLENT', '2026-08-04', 'Sixth studio album by The Beatles, marking their artistic evolution. Features classics like Norwegian Wood, In My Life, and Michelle. Original 1965 pressing.', 'Rock', ARRAY['https://www.thebeatles.com/sites/default/files/styles/max_2600x2600/public/2021-06/Rubber%20Soul.jpg?itok=P8DYZM6d'], 'Rubber Soul - The Beatles', 79.98, 1965, 'Vinilo', 2),
(3, 'Caifanes', 'Caifanes', 'VERY_GOOD', '2026-08-04', 'Debut album of the iconic Mexican rock band Caifanes. Released in 1988, featuring hits like Mátenme Porque Me Muero and La Negra Tomasa. A cornerstone of Latin American rock.', 'Rock en Español', ARRAY['https://www.caifanes.com.mx/assets/extra-images/disco001.jpg'], 'Caifanes - Caifanes', 42.99, 1988, 'Vinilo', 2),
(4, 'Rumours', 'Fleetwood Mac', 'NEAR_MINT', '2026-08-04', 'One of the best-selling albums of all time. A masterpiece of 70s soft rock featuring classics like Dreams, Go Your Own Way, and The Chain.', 'Soft Rock', ARRAY['https://upload.wikimedia.org/wikipedia/en/f/fb/FMacRumours.PNG'], 'Rumours - Fleetwood Mac', 45.00, 1977, 'Vinilo', 2),
(5, 'Thriller', 'Michael Jackson', 'MINT', '2026-08-04', 'The best-selling album of all time featuring legendary hits like Billie Jean, Beat It, and Thriller. A pop masterpiece produced by Quincy Jones.', 'Pop', ARRAY['https://upload.wikimedia.org/wikipedia/en/5/55/Michael_Jackson_-_Thriller.png'], 'Thriller - Michael Jackson', 56.00, 1982, 'Vinilo', 1),
(6, 'Random Access Memories', 'Daft Punk', 'EXCELLENT', '2026-08-22', 'Edición en vinilo de Random Access Memories.', 'Electronic', ARRAY['https://upload.wikimedia.org/wikipedia/en/2/26/Daft_Punk_-_Random_Access_Memories.png?utm_source=en.wikipedia.org&utm_campaign=imageinfo&utm_content=original'], 'Random Access Memories', 35.99, 2013, 'Vinilo', 1),
(7, 'Toxicity', 'System Of A Down', 'EXCELLENT', '2026-08-22', 'Toxicity es el segundo álbum de estudio de la banda armenio-estadounidense de heavy metal System of a Down. Publicado el 4 de septiembre de 2001 por American Recordings, este CD tuvo gran éxito internacional, al vender más de 12 millones de copias a nivel mundial, y dio a conocer a la banda en todo el mundo. Fue asimismo el primer álbum de la banda en liderar las listas de éxitos, y ha sido certificado con seis discos de platino en los Estados Unidos.[2] Forma parte de la lista de los 100 discos que debes tener antes del fin del mundo, publicada en 2012 por Sony Music. La revista Rolling Stone colocó el álbum en el puesto #44 en su lista de los mejores álbumes de la década del 2000.[3] Asimismo, en 2017 lo posicionó en el puesto #27 en su lista "The 100 Greatest Metal Albums of All Time".[4] En enero de 2025, la misma publicación elaboró su lista de los 250 mejores álbumes del siglo XXI, y Toxicity fue uno de los dos únicos álbumes de música metal incluidos y el mejor posicionado (en el puesto 159).', 'Rock', ARRAY['https://upload.wikimedia.org/wikipedia/en/6/64/SystemofaDownToxicityalbumcover.jpg?_=20220822153945'], 'Toxicity - SOAD Excelentes Condiciones', 89.99, 2001, 'Vinilo', 2),
(8, 'Discovery', 'Daft Punk', 'VERY_GOOD', '2026-08-22', 'Segunda producción de estudio de Daft Punk, publicada en 2001. Edición en CD en muy buenas condiciones.', 'Electronic', ARRAY['https://upload.wikimedia.org/wikipedia/en/2/27/Daft_Punk_-_Discovery.png?utm_source=en.wikipedia.org&utm_campaign=imageinfo&utm_content=original'], 'Discovery - Daft Punk', 29.99, 2001, 'CD', 1),
(9, 'Are You Experienced (Vinyl) [Importado] - Nuevo de paquete', 'Jimmy Hendrix', 'MINT', '2026-08-28', 'Descripción del producto\nAre You Experienced es el álbum de estudio debut de la banda de rock inglés-americana Jimi Hendrix Experience.\n\nDetalles del producto\nProducto descontinuado por el fabricante ‏ : ‎ No\nDimensiones del producto ‏ : ‎ 30,48 x 32 x 2,54 cm; 272,16 g\nFabricante ‏ : ‎ Legacy Recordings\nNúmero de modelo del producto ‏ : ‎ 28940204\nFecha de lanzamiento original ‏ : ‎ 2014\nTiempo de ejecución ‏ : ‎ 41 minutos\nEtiqueta ‏ : ‎ Legacy Recordings\nASIN ‏ : ‎ B00JFVORBI\nPaís de origen ‏ : ‎ Estados Unidos\nNúmero de discos ‏ : ‎ 1\nClasificación en los más vendidos de Amazon: nº3,219 en Música (Ver el Top 100 en Música)\nnº18 en Arena Rock\nOpiniones de los clientes: 4.6 4.6 de 5 estrellas   (3,454)', 'Rock', ARRAY['https://m.media-amazon.com/images/I/81Umxm8x4qL._AC_SX385_.jpg'], 'Are You Experienced (Vinyl) [Importado]', 20.00, 1967, 'Vinilo', 6),
(10, 'Master of Puppets', 'Metallica', 'EXCELLENT', '2026-08-29', 'Tercer álbum de estudio de Metallica, publicado en 1986. Uno de los discos más representativos del thrash metal y el último álbum de estudio de la banda con Cliff Burton.', 'Metal', ARRAY['https://en.wikipedia.org/wiki/Special:FilePath/Metallica_-_Master_of_Puppets_cover.jpg'], 'Master of Puppets - Metallica', 64.99, 1986, 'Vinilo', 1),
(11, 'Nevermind', 'Nirvana', 'NEAR_MINT', '2026-08-29', 'Segundo álbum de estudio de Nirvana. Una de las producciones más influyentes del movimiento grunge de los años noventa.', 'Grunge', ARRAY['https://en.wikipedia.org/wiki/Special:FilePath/NirvanaNevermindalbumcover.jpg'], 'Nevermind - Nirvana', 48.50, 1991, 'Vinilo', 1),
(12, 'The Dark Side of the Moon', 'Pink Floyd', 'MINT', '2026-08-29', 'Álbum clásico de Pink Floyd publicado en 1973. Edición en vinilo nueva y en excelentes condiciones.', 'Progressive Rock', ARRAY['https://en.wikipedia.org/wiki/Special:FilePath/Dark_Side_of_the_Moon.png'], 'The Dark Side of the Moon - Pink Floyd', 74.99, 1973, 'Vinilo', 1),
(13, 'Hybrid Theory', 'Linkin Park', 'VERY_GOOD', '2026-08-29', 'Álbum debut de Linkin Park publicado en 2000. Incluye temas como In the End, Crawling y One Step Closer.', 'Nu Metal', ARRAY['https://en.wikipedia.org/wiki/Special:FilePath/Linkin_Park_Hybrid_Theory_Album_Cover.jpg'], 'Hybrid Theory - Linkin Park', 24.99, 2000, 'CD', 1),
(14, 'Dookie', 'Green Day', 'GOOD', '2026-08-29', 'Tercer álbum de estudio de Green Day. Un clásico del punk rock de los años noventa.', 'Punk Rock', ARRAY['https://en.wikipedia.org/wiki/Special:FilePath/Green_Day_-_Dookie_cover.jpg'], 'Dookie - Green Day', 18.50, 1994, 'Cassette', 1),
(15, 'A Night at the Opera', 'Queen', 'NEAR_MINT', '2026-08-29', 'Cuarto álbum de estudio de Queen. Incluye uno de los temas más conocidos de la banda: Bohemian Rhapsody.', 'Rock', ARRAY['https://en.wikipedia.org/wiki/Special:FilePath/Queen_A_Night_At_The_Opera.png'], 'A Night at the Opera - Queen', 58.00, 1975, 'Vinilo', 2),
(16, 'Canción Animal', 'Soda Stereo', 'EXCELLENT', '2026-08-29', 'Quinto álbum de estudio de Soda Stereo, publicado en 1990. Incluye clásicos del rock en español como De Música Ligera.', 'Rock en Español', ARRAY['https://coverartarchive.org/release/43500162-0628-431f-90e4-8417eec3b6b5/front-500'], 'Canción Animal - Soda Stereo', 49.99, 1990, 'Vinilo', 2),
(17, 'Re', 'Café Tacvba', 'VERY_GOOD', '2026-08-29', 'Segundo álbum de estudio de Café Tacvba y uno de los trabajos más representativos del rock alternativo mexicano.', 'Rock en Español', ARRAY['https://i.pinimg.com/736x/32/1c/83/321c83ba6c493c4c2c89d9591582c4d1.jpg'], 'Re - Café Tacvba', 34.50, 1994, 'CD', 2),
(18, 'AM', 'Arctic Monkeys', 'MINT', '2026-08-29', 'Quinto álbum de estudio de Arctic Monkeys. Edición en vinilo en condición impecable.', 'Indie Rock', ARRAY['https://en.wikipedia.org/wiki/Special:FilePath/Arctic_Monkeys_-_AM.png'], 'AM - Arctic Monkeys', 42.99, 2013, 'Vinilo', 2),
(19, 'Demon Days', 'Gorillaz', 'EXCELLENT', '2026-08-29', 'Segundo álbum de estudio de Gorillaz. Incluye canciones como Feel Good Inc. y DARE.', 'Alternative', ARRAY['https://en.wikipedia.org/wiki/Special:FilePath/Gorillaz_Demon_Days.PNG'], 'Demon Days - Gorillaz', 27.99, 2005, 'CD', 2),
(20, 'Disintegration', 'The Cure', 'NEAR_MINT', '2026-08-29', 'Octavo álbum de estudio de The Cure. Una de las producciones más reconocidas de la banda británica.', 'Alternative Rock', ARRAY['https://elevenstore.cl/elevenstore/7423-thickbox_default/the-cure-disintegration-cd.jpg'], 'Disintegration - The Cure', 52.00, 1989, 'Vinilo', 3),
(21, 'OK Computer', 'Radiohead', 'EXCELLENT', '2026-08-29', 'Tercer álbum de estudio de Radiohead. Edición en vinilo muy bien conservada.', 'Alternative Rock', ARRAY['https://en.wikipedia.org/wiki/Special:FilePath/Radioheadokcomputer.png'], 'OK Computer - Radiohead', 59.99, 1997, 'Vinilo', 3),
