(23, 'The Number of the Beast', 'Iron Maiden', 'GOOD', '2026-08-29', 'Tercer álbum de estudio de Iron Maiden y una de las producciones más conocidas de la banda.', 'Heavy Metal', ARRAY['https://en.wikipedia.org/wiki/Special:FilePath/Iron_Maiden_-_The_Number_Of_The_Beast.jpg'], 'The Number of the Beast - Iron Maiden', 29.99, 1982, 'Cassette', 3),
(24, 'Californication', 'Red Hot Chili Peppers', 'MINT', '2026-08-29', 'Séptimo álbum de estudio de Red Hot Chili Peppers, publicado en 1999 y producido por Rick Rubin.', 'Alternative Rock', ARRAY['https://en.wikipedia.org/wiki/Special:FilePath/RedHotChiliPeppersCalifornication.jpg'], 'Californication - Red Hot Chili Peppers', 46.90, 1999, 'Vinilo', 3),
(25, 'Violator', 'Depeche Mode', 'EXCELLENT', '2026-08-29', 'Séptimo álbum de estudio de Depeche Mode. Incluye temas como Personal Jesus y Enjoy the Silence.', 'Electronic', ARRAY['https://en.wikipedia.org/wiki/Special:FilePath/Depeche_Mode_-_Violator.png'], 'Violator - Depeche Mode', 44.99, 1990, 'Vinilo', 6),
